<?php
declare(strict_types=1);require dirname(__DIR__).'/private/app/bootstrap.php';$pdo=db();$pdo->exec('CREATE TABLE IF NOT EXISTS migrations (id INT AUTO_INCREMENT PRIMARY KEY,migration VARCHAR(180) UNIQUE,executed_at DATETIME NOT NULL)');foreach(glob(__DIR__.'/migrations/*.sql')as$file){$name=basename($file);$q=$pdo->prepare('SELECT 1 FROM migrations WHERE migration=?');$q->execute([$name]);if($q->fetchColumn())continue;try{$pdo->exec(file_get_contents($file));$q=$pdo->prepare('INSERT INTO migrations(migration,executed_at) VALUES(?,NOW())');$q->execute([$name]);echo"Migrated: $name\n";}catch(Throwable$e){throw$e;}}
